/**
 * MorphoNews Layout: テクトニック・シフト・フラクチャー
 * Generation: #89
 * Mood: Structural-Disruption
 * Evolution: Vertical Asynchronous Column Scroll + Tectonic Clipping Reveal
 */

:root {
    --layout-max-width: 1400px;
    --layout-news-columns: repeat(2, 1fr);
    --layout-card-gap: 6rem;
    --layout-card-direction: column;
    --layout-animation-style: tectonic-slide;
    --fracture-intensity: 15%;
}

#news-container {
    display: grid;
    grid-template-columns: var(--layout-news-columns);
    gap: var(--layout-card-gap);
    max-width: var(--layout-max-width);
    margin: 0 auto;
    padding: 10vh 2rem;
    perspective: 1500px;
}

/* 左カラムと右カラムに異なるスクロール挙動を与える */
.news-card:nth-child(odd) {
    transform: translateY(100px);
    animation: scroll-drift-up linear both;
    animation-timeline: scroll();
}

.news-card:nth-child(even) {
    transform: translateY(-100px);
    animation: scroll-drift-down linear both;
    animation-timeline: scroll();
    margin-top: 15vh;
}

@keyframes scroll-drift-up {
    from { transform: translateY(150px); }
    to { transform: translateY(-150px); }
}

@keyframes scroll-drift-down {
    from { transform: translateY(-150px); }
    to { transform: translateY(150px); }
}

.news-card {
    position: relative;
    background: var(--morpho-bg-secondary);
    border-left: 4px solid var(--morpho-accent-primary);
    padding: 0;
    overflow: visible;
    transition: clip-path 0.6s cubic-bezier(0.23, 1, 0.32, 1);
    /* 断層のようなクリッピングパス */
    clip-path: polygon(
        0% var(--fracture-intensity), 
        100% 0%, 
        100% calc(100% - var(--fracture-intensity)), 
        0% 100%
    );
}

.news-card::before {
    content: '';
    position: absolute;
    inset: 0;
    background: var(--morpho-accent-gradient);
    opacity: 0.03;
    z-index: 0;
    pointer-events: none;
}

.news-card-inner {
    padding: 3rem;
    z-index: 1;
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.news-card:hover {
    /* ホバー時に「破壊」が修復されるような視覚効果 */
    clip-path: polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%);
    border-left-width: 12px;
}

.news-card-number {
    position: absolute;
    bottom: -1rem;
    right: 1rem;
    font-family: 'Fira Code', monospace;
    font-size: 8rem;
    font-weight: 900;
    line-height: 1;
    color: var(--morpho-accent-primary);
    opacity: 0.1;
    z-index: -1;
    transition: transform 0.4s ease;
}

.news-card:hover .news-card-number {
    transform: scale(1.2) translateY(-20px);
    opacity: 0.2;
}

